package run.ikaros.sharing; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException; @Service public class PersistentRoomEventService implements RoomEventService{private final RoomRepository rooms;private final RoomMembershipRepository members;private final RoomEventRepository events;public PersistentRoomEventService(RoomRepository r,RoomMembershipRepository m,RoomEventRepository e){rooms=r;members=m;events=e;}public Mono<RoomEventView> append(UUID a,UUID id,AppendRoomEventRequest q){return access(a,id).flatMap(room->{if(room.status()!=RoomStatus.ACTIVE)return Mono.error(new ConflictException("Room 当前不可修改"));if(q.expectedStateVersion()!=null&&q.expectedStateVersion()!=room.stateVersion())return Mono.error(new ConflictException("Room State Version 冲突"));long seq=room.sequence()+1,sv=room.stateVersion()+1;Instant now=Instant.now();return rooms.save(new RoomEntity(room.id(),room.ownerId(),room.kind(),room.targetType(),room.targetId(),room.visibility(),room.status(),sv,seq,room.expiresAt(),room.createdAt(),now,room.version())).then(events.save(new RoomEventEntity(null,id,seq,q.eventType(),a,now,q.payload(),sv))).map(this::view);});}public Flux<RoomEventView> replay(UUID a,UUID id,long after){return access(a,id).thenMany(events.findAllByRoomIdAndSequenceGreaterThanOrderBySequenceAsc(id,after).map(this::view));}private Mono<RoomEntity> access(UUID a,UUID id){return rooms.findById(id).flatMap(r->r.ownerId().equals(a)?Mono.just(r):members.findByRoomIdAndPrincipalId(id,a).filter(m->m.leftAt()==null).thenReturn(r)).switchIfEmpty(Mono.error(new NotFoundException("Room 不存在或无权访问")));}private RoomEventView view(RoomEventEntity e){return new RoomEventView(e.eventId(),e.roomId(),e.sequence(),e.eventType(),e.actorId(),e.occurredAt(),e.payload(),e.stateVersion());}}
